import { Interactive, Sequence, useCurrentFrame, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";
import { forwardRef, useImperativeHandle, useRef, type ComponentProps } from "react";

interface InfiniteMarqueeProps {
  text?: string;
  fontSize?: number;
  color?: string;
  fontWeight?: number;
  pixelsPerFrame?: number;
  stroke?: boolean;
  strokeColor?: string;
  speed?: number;
  className?: string;
}

function InfiniteMarqueeBase({
  text = "ship · build · animate · ",
  fontSize = 120,
  color = "#171717",
  fontWeight = 900,
  pixelsPerFrame = 4,
  stroke = false,
  strokeColor = "#171717",
  speed = 1,
  className,
}: InfiniteMarqueeProps) {
  const frame = useCurrentFrame() * speed;

  const approxWidth = text.length * fontSize * 0.55;
  const offset = -((frame * pixelsPerFrame) % approxWidth);

  const spanStyle: React.CSSProperties = {
    fontSize,
    fontWeight,
    fontFamily:
      "var(--font-geist-sans), -apple-system, BlinkMacSystemFont, sans-serif",
    color: stroke ? "transparent" : color,
    WebkitTextStroke: stroke ? `2px ${strokeColor}` : undefined,
    paddingRight: "0.4em",
    letterSpacing: "-0.03em",
  };

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      <div
        className={className}
        style={{
          display: "flex",
          whiteSpace: "nowrap",
          transform: `translateX(${offset}px)`,
        }}
      >
        <span style={spanStyle}>{text}</span>
        <span style={spanStyle}>{text}</span>
        <span style={spanStyle}>{text}</span>
      </div>
    </div>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  text: {
    type: "text-content",
    default: "ship · build · animate · ",
    description: "Text",
  },
  fontSize: {
    type: "number",
    min: 12,
    max: 240,
    step: 1,
    default: 120,
    description: "Font size",
    hiddenFromList: false,
  },
  color: {
    type: "color",
    default: "#171717",
    description: "Color",
  },
  fontWeight: {
    type: "enum",
    default: "700",
    variants: {
      "400": {},
      "500": {},
      "600": {},
      "700": {},
    },
    description: "Font weight",
  },
  pixelsPerFrame: {
    type: "number",
    min: 1,
    max: 30,
    step: 1,
    default: 4,
    description: "Pixels / frame",
    hiddenFromList: false,
  },
  stroke: {
    type: "boolean",
    default: false,
    description: "Stroke",
  },
  strokeColor: {
    type: "color",
    default: "#171717",
    description: "Stroke color",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["text","fontSize","color","fontWeight","pixelsPerFrame","stroke","strokeColor","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  text: "ship · build · animate · ",
  fontSize: 120,
  color: "#171717",
  fontWeight: "700",
  pixelsPerFrame: 4,
  stroke: false,
  strokeColor: "#171717",
  speed: 1,
};

type InfiniteMarqueeElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof InfiniteMarqueeBase>;

const InfiniteMarqueeInner = forwardRef<
  HTMLDivElement,
  InfiniteMarqueeElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<InfiniteMarquee>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <InfiniteMarqueeBase
          {...(componentProps as unknown as ComponentProps<typeof InfiniteMarqueeBase>)}
        />
      </div>
    </Sequence>
  );
});

export const InfiniteMarquee = Interactive.withSchema({
  Component: InfiniteMarqueeInner,
  componentName: "<InfiniteMarquee>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
